html:
{% set is_draft = doc.docstatus == 0 %}
{% set is_cancelled = doc.docstatus == 2 %}
{% set token = doc.ts_token %}
{% set has_chain = token and not doc.ts_non_weighing_grn and not doc.ts_direct_po_grn %}
{% set rst_number = frappe.db.get_value('TS Weighbridge Log', {'token_number': token}, 'rst_number') if token else None %}
{% set qi_name = frappe.db.get_value('TS Quality Inspection', {'token_number': token, 'docstatus': 1}, 'name') if token else None %}
{% set ds_name = frappe.db.get_value('TS Deduction Sheet', {'quality_inspection': qi_name, 'docstatus': 1}, 'name') if qi_name else None %}
{% set ns = namespace(first_po='', first_mr='', first_cc='', first_loc='') %}
{% for it in doc.items %}{% if it.purchase_order and not ns.first_po %}{% set ns.first_po = it.purchase_order %}{% endif %}{% if it.material_request and not ns.first_mr %}{% set ns.first_mr = it.material_request %}{% endif %}{% if it.cost_center and not ns.first_cc %}{% set ns.first_cc = it.cost_center %}{% endif %}{% if it.ts_delivery_location and not ns.first_loc %}{% set ns.first_loc = it.ts_delivery_location %}{% endif %}{% endfor %}
{% set first_po = ns.first_po %}{% set first_mr = ns.first_mr %}{% set first_cc = ns.first_cc %}{% set first_loc = ns.first_loc %}
{% set supp_addr = frappe.get_doc('Address', doc.supplier_address) if doc.supplier_address else None %}

<style>
@page { size: A4; margin: 6mm 8mm 6mm 8mm; }
body { font-family: Arial, sans-serif; font-size: 10px; color: #000; }
.trustbit-wrap { position: relative; }
.trustbit-header-table { width: 100%; border-collapse: collapse; border: none; padding: 0 0 6px 0; }
.trustbit-header-table td { border: none !important; padding: 0; vertical-align: middle; }
.trustbit-logo-cell { width: 110px; padding-left: 6px !important; }
.trustbit-logo-cell img { max-width: 95px; max-height: 75px; }
.trustbit-header-text { text-align: center; padding-right: 110px !important; }
.trustbit-header-bottom-rule { border-bottom: 2px solid #000; margin: 0 0 6px 0; height: 0; line-height: 0; }
.trustbit-cname { font-size: 20px; font-weight: bold; color: #000; letter-spacing: 0.5px; line-height: 1.2; }
.trustbit-caddr { font-size: 12px; font-weight: bold; text-decoration: underline; margin-top: 2px; }
.trustbit-cinfo { font-size: 10px; margin-top: 3px; color: #111; }
.trustbit-cinfo span { margin: 0 6px; }
.trustbit-title-block { text-align: center; margin: 6px 0 4px 0; }
.trustbit-draft-stamp { font-size: 13px; font-weight: bold; letter-spacing: 2px; margin-bottom: 2px; }
.trustbit-title { font-size: 16px; font-weight: bold; text-decoration: underline; letter-spacing: 1px; }
.trustbit-info-table { width: 100%; border-collapse: collapse; margin: 0 0 4px 0; }
.trustbit-info-table td { padding: 3px 6px; font-size: 11px; vertical-align: middle; border: 1px solid #000; }
.trustbit-info-label { font-weight: bold; width: 22%; background: #eee; text-align: center; }
.trustbit-info-value { width: 28%; text-align: center; }
.trustbit-section-heading { font-size: 12px; font-weight: bold; text-decoration: underline; margin: 8px 0 3px; }
.trustbit-context-table { width: 100%; border-collapse: collapse; margin: 0 0 4px 0; }
.trustbit-context-table td { padding: 3px 6px; font-size: 11px; vertical-align: middle; border: 1px solid #000; }
.trustbit-context-label { font-weight: bold; width: 22%; background: #f5f5e8; text-align: center; }
.trustbit-context-value { width: 28%; text-align: center; }
.trustbit-items { width: 100%; border-collapse: collapse; margin: 4px 0 0 0; }
.trustbit-items th { background: #e8e8e8; border: 1px solid #000; padding: 4px 6px; font-size: 10px; text-align: center; font-weight: bold; }
.trustbit-items td { border: 1px solid #000; padding: 3px 6px; font-size: 11px; vertical-align: top; }
.trustbit-items .num { text-align: right; }
.trustbit-items .ctr { text-align: center; }
.trustbit-items .item-spec { font-size: 10px; color: #111; margin-top: 3px; line-height: 1.4; }
.trustbit-items tfoot td { padding: 4px 6px; font-size: 11px; font-weight: bold; }
.trustbit-items tfoot .total-lbl { text-align: right; background: #eee; }
.trustbit-items tfoot .total-val { text-align: right; }
.trustbit-items tfoot .grand .total-lbl, .trustbit-items tfoot .grand .total-val { background: #cce6ff; font-size: 12px; }
.trustbit-in-words { font-size: 11px; padding: 4px 6px; margin-top: 2px; border: 1px solid #000; background: #fafafa; font-style: italic; }
.trustbit-sign-table { width: 100%; border-collapse: collapse; margin: 12px 0 0 0; }
.trustbit-sign-table td { border: none !important; padding: 0 6px; vertical-align: top; width: 50%; }
.trustbit-sign-box { border-top: 1px solid #000; padding-top: 3px; text-align: center; font-size: 11px; font-weight: bold; }
.trustbit-sign-box .sub { display: block; font-weight: normal; font-size: 9px; color: #333; margin-top: 1px; }
.trustbit-sign-spacer { height: 22px; }
.trustbit-footer { margin-top: 8px; border-top: 1px solid #000; padding-top: 4px; text-align: center; font-size: 9px; color: #111; line-height: 1.3; page-break-inside: avoid; }
.trustbit-footer .fname { font-weight: bold; font-size: 10px; color: #000; }
.trustbit-sign-table, .trustbit-context-table, .trustbit-info-table { page-break-inside: avoid; }
.trustbit-watermark { position: fixed; top: 35%; left: 8%; font-size: 110px; color: rgba(255,0,0,0.08); font-weight: bold; transform: rotate(-30deg); -webkit-transform: rotate(-30deg); z-index: 0; letter-spacing: 18px; pointer-events: none; }
@media print {
  .letter-head .header, .letter-head { position: static !important; top: auto !important; left: auto !important; right: auto !important; }
  .letter-head body { margin: 0 !important; padding: 0 !important; }
}
</style>

<div class="trustbit-wrap">

{% if is_draft %}<div class="trustbit-watermark">DRAFT</div>{% endif %}
{% if is_cancelled %}<div class="trustbit-watermark" style="color: rgba(0,0,0,0.10);">CANCELLED</div>{% endif %}

{% if letter_head and not no_letterhead %}<div class="letter-head">{{ letter_head | safe }}</div>{% endif %}

{% if not letter_head or no_letterhead %}
<table class="trustbit-header-table">
<tr>
  <td class="trustbit-logo-cell">
    <img src="/files/client_logo.png" alt="Trustbit" onerror="this.style.display='none'">
  </td>
  <td class="trustbit-header-text">
    <div class="trustbit-cname">TRUSTBIT BIOFUEL PVT LTD</div>
    <div class="trustbit-caddr">Bodi Junawani, Betul (M.P.)</div>
    <div class="trustbit-cinfo">
      <span><b>GSTN:-</b> 23AAJCB8781D1ZM</span>
    </div>
    <div class="trustbit-cinfo">
      <span><b>Email:-</b> trustbitbiofuelpvtld@gmail.com | <b>Mobile no:-</b> 7880138508</span>
    </div>
  </td>
</tr>
</table>
<div class="trustbit-header-bottom-rule"></div>
{% endif %}

<div class="trustbit-title-block">
  {% if is_draft %}<div class="trustbit-draft-stamp" style="color:#cc0000;">DRAFT</div>{% endif %}
  {% if is_cancelled %}<div class="trustbit-draft-stamp" style="color:#000;">CANCELLED</div>{% endif %}
  <div class="trustbit-title">PURCHASE RECEIPT</div>
</div>

<table class="trustbit-info-table">
<tr>
  <td class="trustbit-info-label">Receipt No</td>
  <td class="trustbit-info-value">{{ doc.name }}</td>
  <td class="trustbit-info-label">Posting Date</td>
  <td class="trustbit-info-value">{{ frappe.format(doc.posting_date, {'fieldtype': 'Date'}) }}</td>
</tr>
<tr>
  <td class="trustbit-info-label">Supplier</td>
  <td class="trustbit-info-value">{{ doc.supplier_name or doc.supplier or '' }}</td>
  <td class="trustbit-info-label">Supplier Invoice No / Date</td>
  <td class="trustbit-info-value">{{ doc.bill_no or '-' }}{% if doc.bill_date %} <br><span style="font-size:10px;">{{ frappe.format(doc.bill_date, {'fieldtype': 'Date'}) }}</span>{% endif %}</td>
</tr>
{% if supp_addr %}
<tr>
  <td class="trustbit-info-label">Supplier Address</td>
  <td colspan="3" class="trustbit-info-value" style="text-align:left;">{{ supp_addr.address_line1 or '' }}{% if supp_addr.address_line2 %}, {{ supp_addr.address_line2 }}{% endif %}{% if supp_addr.city %}, {{ supp_addr.city }}{% endif %}{% if supp_addr.state %}, {{ supp_addr.state }}{% endif %}{% if supp_addr.pincode %} - {{ supp_addr.pincode }}{% endif %}{% if supp_addr.country %}, {{ supp_addr.country }}{% endif %}</td>
</tr>
{% endif %}
<tr>
  <td class="trustbit-info-label">Vehicle No</td>
  <td class="trustbit-info-value">{{ doc.vehicle_no or '-' }}</td>
  <td class="trustbit-info-label">Vehicle Origin</td>
  <td class="trustbit-info-value">{{ doc.vehicle_origin or '-' }}</td>
</tr>
<tr>
  <td class="trustbit-info-label">LR No</td>
  <td class="trustbit-info-value">{{ doc.lr_no or '-' }}</td>
  <td class="trustbit-info-label">Transporter</td>
  <td class="trustbit-info-value">{{ doc.transporter_name or '-' }}</td>
</tr>
<tr>
  <td class="trustbit-info-label">Warehouse</td>
  <td class="trustbit-info-value">{{ doc.set_warehouse or '-' }}</td>
  <td class="trustbit-info-label">Cost Center</td>
  <td class="trustbit-info-value">{{ first_cc or '-' }}</td>
</tr>
<tr>
  <td class="trustbit-info-label">Project</td>
  <td class="trustbit-info-value">{{ doc.project or '-' }}</td>
  <td class="trustbit-info-label">Status</td>
  <td class="trustbit-info-value">{{ doc.status or '-' }}</td>
</tr>
{% if first_loc %}
<tr>
  <td class="trustbit-info-label">Location (From PO)</td>
  <td colspan="3" class="trustbit-info-value" style="text-align:left;">{{ first_loc }}</td>
</tr>
{% endif %}
</table>

{% if token or rst_number or qi_name or ds_name or doc.ts_wb_net_kg %}
<div class="trustbit-section-heading">Receipt Context</div>
<table class="trustbit-context-table">
<tr>
  <td class="trustbit-context-label">Token No</td>
  <td class="trustbit-context-value">{{ token or '-' }}</td>
  <td class="trustbit-context-label">Gate Entry</td>
  <td class="trustbit-context-value">{{ doc.ts_gate_entry or '-' }}</td>
</tr>
<tr>
  <td class="trustbit-context-label">RST No</td>
  <td class="trustbit-context-value">{{ rst_number or '-' }}</td>
  <td class="trustbit-context-label">WB Net (KG)</td>
  <td class="trustbit-context-value">{% if doc.ts_wb_net_kg %}{{ frappe.format(doc.ts_wb_net_kg, {'fieldtype': 'Float', 'precision': 2}) }}{% else %}-{% endif %}</td>
</tr>
<tr>
  <td class="trustbit-context-label">Quality Inspection</td>
  <td class="trustbit-context-value">{{ qi_name or '-' }}</td>
  <td class="trustbit-context-label">Deduction Sheet</td>
  <td class="trustbit-context-value">{{ ds_name or '-' }}</td>
</tr>
<tr>
  <td class="trustbit-context-label">Source PO</td>
  <td class="trustbit-context-value">{{ first_po or '-' }}</td>
  <td class="trustbit-context-label">QC Status</td>
  <td class="trustbit-context-value">{{ doc.ts_qc_status or '-' }}</td>
</tr>
{% if first_mr %}
<tr>
  <td class="trustbit-context-label">Material Request</td>
  <td colspan="3" class="trustbit-context-value">{{ first_mr }}</td>
</tr>
{% endif %}
</table>
{% endif %}

<table class="trustbit-items">
<thead>
<tr>
  <th style="width:36px">S.No</th>
  <th>Item</th>
  <th style="width:65px">Quantity</th>
  <th style="width:50px">Unit</th>
  <th style="width:78px">Rate</th>
  <th style="width:90px">GST</th>
  <th style="width:95px">Amount</th>
</tr>
</thead>
<tbody>
{% for item in doc.items %}
{% set tax_ns = namespace(amt=0, rate=0, label='') %}
{% if item.item_tax_template %}{% set _tpl = item.item_tax_template %}{% set _parts = _tpl.split('%') %}{% if _parts | length > 1 %}{% set _nums = _parts[0].replace('GST','').replace('-','').strip() %}{% if _nums %}{% set tax_ns.rate = _nums | float %}{% set tax_ns.amt = (item.amount or 0) * tax_ns.rate / 100 %}{% set tax_ns.label = 'GST' %}{% endif %}{% endif %}{% endif %}
{% if tax_ns.amt == 0 and (doc.taxes or []) %}{% set _t0 = doc.taxes[0] %}{% if _t0.rate and _t0.rate > 0 %}{% set tax_ns.rate = _t0.rate %}{% set tax_ns.amt = (item.amount or 0) * tax_ns.rate / 100 %}{% if 'IGST' in (_t0.account_head or '') %}{% set tax_ns.label = 'IGST' %}{% elif 'CGST' in (_t0.account_head or '') or 'SGST' in (_t0.account_head or '') %}{% set tax_ns.label = 'GST' %}{% else %}{% set tax_ns.label = 'GST' %}{% endif %}{% endif %}{% endif %}
<tr>
  <td class="ctr">{{ loop.index }}</td>
  <td><b>{{ item.item_name or item.item_code }}</b>{% if item.description and item.description != (item.item_name or item.item_code) %}<div class="item-spec">{{ item.description | safe }}</div>{% endif %}</td>
  <td class="num">{{ frappe.format(item.qty, {'fieldtype': 'Float', 'precision': 2}) }}</td>
  <td class="ctr">{{ item.uom or item.stock_uom }}</td>
  <td class="num">{{ frappe.format(item.rate, {'fieldtype': 'Currency'}) }}</td>
  <td class="num">{% if tax_ns.amt > 0 %}<b>{{ frappe.format(tax_ns.amt, {'fieldtype': 'Currency'}) }}</b><br><span style="font-size:9px;color:#444;">{{ tax_ns.label or 'GST' }} {{ (tax_ns.rate | int) if tax_ns.rate == (tax_ns.rate | int) else tax_ns.rate }}%</span>{% else %}<span style="color:#666;font-size:10px;">Exempt</span>{% endif %}</td>
  <td class="num">{{ frappe.format(item.amount, {'fieldtype': 'Currency'}) }}</td>
</tr>
{% endfor %}
</tbody>
<tfoot>
<tr>
  <td colspan="6" class="total-lbl">Net Total</td>
  <td class="total-val">{{ frappe.format(doc.net_total, {'fieldtype': 'Currency'}) }}</td>
</tr>
{% for tax in doc.taxes %}
<tr>
  <td colspan="6" class="total-lbl">{{ tax.description or 'Tax' }}</td>
  <td class="total-val">{{ frappe.format(tax.tax_amount, {'fieldtype': 'Currency'}) }}</td>
</tr>
{% endfor %}
<tr class="grand">
  <td colspan="6" class="total-lbl">Grand Total</td>
  <td class="total-val">{{ frappe.format(doc.grand_total, {'fieldtype': 'Currency'}) }}</td>
</tr>
</tfoot>
</table>

{% if doc.in_words %}
<div class="trustbit-in-words"><b>Amount in Words:</b> {{ doc.in_words }}</div>
{% endif %}

{% if doc.tc_name or doc.terms %}
<div class="trustbit-section-heading">Terms and Conditions</div>
<div class="trustbit-in-words" style="font-style:normal;">{{ doc.terms or '' | safe }}</div>
{% endif %}

<table class="trustbit-sign-table">
<tr>
  <td>
    <div class="trustbit-sign-spacer"></div>
    <div class="trustbit-sign-box">Received By (Stores)<span class="sub">Name &amp; Signature / Date</span></div>
  </td>
  <td>
    <div class="trustbit-sign-spacer"></div>
    <div class="trustbit-sign-box">Verified By (Quality)<span class="sub">Name &amp; Signature / Date</span></div>
  </td>
</tr>
</table>

<div class="trustbit-footer">
  <div class="fname">TRUSTBIT BIOFUEL PVT LTD</div>
  <div>Bodi Junawani, Betul (M.P.)</div>
  <div>GSTN:- 23AAJCB8781D1ZM</div>
  <div>Email:- trustbitbiofuelpvtld@gmail.com | Mobile no:- 7880138508</div>
</div>

</div>
